/* Manual-car guided practice; the selected sequence is for this training vehicle. */
(()=>{const S=DriveSimulation,W=DriveWorld;let active=false,step=0,stage=0,hold=0,mistakes=0,reverse=false,rampArmed=false;let state;let gear="N",lastDrive="R";const pedals={go:false,brake:false,clutch:false};function releasePedals(){for(const k in pedals)pedals[k]=false;}
const steps=[['seat','Reglează scaunul','Poziție confortabilă: ajungi la pedale fără să întinzi complet piciorul.'],['mirrors','Reglează oglinzile','Verifică vizibilitatea în spate și lateral.'],['belt','Pune centura','Centura se fixează înainte de deplasare.'],['brake','Apasă frâna','Ține mașina imobilizată; frâna de mână rămâne trasă.'],['neutral','Verifică punctul mort','Verifică dacă schimbătorul este în poziția neutră.'],['clutch','Apasă ambreiajul','Apasă complet ambreiajul înainte de pornire.'],['ignition','Pornește motorul','Rotește cheia, apoi verifică martorii de bord.'],['lights','Aprinde luminile','Activează luminile de întâlnire ale mașinii de exercițiu.'],['gear','Selectează treapta 1','Ține ambreiajul apăsat.'],['look','Asigură-te și semnalizează','Verifică oglinzile și unghiul mort înainte de plecare.'],['handbrake','Eliberează frâna de mână','Ține frâna de serviciu apăsată.'],['go','Pleacă ușor','Eliberează treptat ambreiajul și accelerează lin.']];
const tasks=[{x:1,z:29,a:0,title:'Plecare și oprire',text:'Pedale cu mouse-ul sau W / SPACE · A/D: direcție. Oprește în zona verde.'},{x:7,z:35,a:-Math.PI/2,title:'Parcare cu spatele',text:'Ocolește conurile, selectează R și intră cu spatele în locul marcat. Oprește drept.'},{x:13,z:29,a:0,title:'Parcare laterală',text:'Intră între conuri cu mers înapoi. Oprește paralel cu marcajul, cu fața spre dreapta.'},{x:18,z:32,a:-Math.PI/2,title:'Pornire în rampă',text:'Urcă rampa, oprește în zona de sus și ține SPACE 3 secunde. Apoi pornește înainte fără să cobori înapoi.'},{x:18,z:27,a:0,title:'Final de traseu',text:'Oprește în zona de final fără să atingi conurile.'}];
const cones=[];for(const t of tasks)if(t!==tasks[3])for(const side of [-1,1])for(let i=-2;i<=2;i++)cones.push({x:t.x+(t.a===0?i*.65:side*.9),z:t.z+(t.a===0?side*.9:i*.65)});
const road=W.roadAt;W.roadAt=(x,z,m=0)=>(x>-5+m&&x<21-m&&z>26+m&&z<38-m)||road(x,z,m);
const ui=document.createElement('section');ui.className='cockpit';ui.hidden=true;ui.innerHTML='<div class="training-instruction"><strong id="training-title"></strong><p id="training-copy"></p><span id="training-status"></span><button id="training-exit">Ieși din lecție</button></div><div class="cockpit-dashboard"><div class="wheel">◉</div><div class="instruments"><b id="training-speed">0 KM/H</b><span id="training-gear">N</span><small>MAȘINĂ CU TRANSMISIE MANUALĂ · EXERCIȚIU GHIDAT</small></div><div class="cockpit-controls"></div></div>';document.querySelector('.scene-wrap').append(ui);
const controls=ui.querySelector('.cockpit-controls');function say(t){ui.querySelector('#training-status').textContent=t;}function display(){ui.querySelector('#training-title').textContent=stage<0?`Pornirea mașinii · ${step+1}/${steps.length}`:`Poligon · ${stage+1}/5 · ${tasks[stage]?.title||'Terminat'}`;ui.querySelector('#training-copy').textContent=stage<0?steps[step][1]+' — '+steps[step][2]:tasks[stage]?.text||'Exerciții încheiate.';}
function clickControl(id){if(!active)return;if(stage>=0){if(id==='neutral'||id==='gear'||id==='first'||id==='reverse'){if(Math.abs(state.player.speed)>.05)return say('Oprește înainte de schimbarea sensului.');if(!pedals.clutch)return say('Ține apăsat ambreiajul înainte să schimbi viteza.');if(id==='neutral'){gear='N';reverse=false;}else{if(gear!=='N')return say('Selectează N (neutru), apoi treapta dorită.');gear=id==='first'?'1':id==='reverse'?'R':lastDrive==='1'?'R':'1';lastDrive=gear;reverse=gear==='R';}say('Treapta '+gear+' · eliberează ambreiajul pentru plecare.');}return;}if(id!==steps[step][0])return say('Următorul pas: '+steps[step][1]);step++;if(step===steps.length){stage=0;gear='1';lastDrive='1';releasePedals();state.paused=false;say('Motor pornit · Ține pedala de accelerație. Schimbare: ambreiaj → N → 1 / R.');}else say('Următorul pas: '+steps[step][1]);display();}
function start(s){state=s;releasePedals();gear="N";active=true;step=0;stage=-1;hold=0;mistakes=0;reverse=false;rampArmed=false;s.paused=true;s.failed=false;s.traffic=s.traffic.filter(t=>t.x>23||t.z<24||t.z>40);s.scenario=null;Object.assign(s.player,{x:-2,z:35,angle:0,speed:0});ui.hidden=false;ui.querySelectorAll('[data-control]').forEach(b=>{b.classList.remove('done');b.hidden=false;});controls.querySelectorAll('[data-gear]').forEach(b=>b.remove());display();say('Începe cu: '+steps[0][1]);}
ui.querySelector('#training-exit').onclick=()=>{active=false;releasePedals();ui.hidden=true;state.paused=false;Object.assign(state.player,{x:24.78,z:32,angle:-Math.PI/2,speed:0});};
const objective=S.objective;S.objective=s=>active?{title:'Poligon · '+(stage<0?'Pregătirea mașinii':tasks[stage]?.title||'Final'),text:stage<0?steps[step]?.[1]:tasks[stage]?.text,target:stage>=0?tasks[stage]:null,distance:stage>=0?Math.hypot(s.player.x-tasks[stage].x,s.player.z-tasks[stage].z):0,service:true}:objective(s);
const update=S.update;S.update=(s,input,dt)=>{if(!active)return update(s,input,dt);state=s;if(stage<0)return;const old={x:s.player.x,z:s.player.z};const throttle=(input.w||pedals.go)&&gear!=="N"&&!pedals.clutch;input={...input,w:throttle,space:input.space||input.s||pedals.brake};const applied={...input,w:!reverse&&throttle,s:reverse&&throttle};update(s,applied,dt);const p=s.player;if(cones.some(c=>{const dx=c.x-p.x,dz=c.z-p.z,f=dx*Math.cos(p.angle)+dz*Math.sin(p.angle),r=-dx*Math.sin(p.angle)+dz*Math.cos(p.angle);return Math.abs(f)<.62&&Math.abs(r)<.37;})){p.x=old.x;p.z=old.z;p.speed=0;mistakes++;say('Ai atins un con. Reia manevra; conurile trebuie evitate. Greșeli: '+mistakes);}
if(p.x>17&&p.x<19&&p.z>32.5&&p.z<34.5&&!input.space&&!input.w){p.z+=dt*.12;say('Mașina tinde să ruleze înapoi. Ține frâna.');}
const t=tasks[stage],near=Math.hypot(p.x-t.x,p.z-t.z)<1.15,aligned=Math.abs(Math.atan2(Math.sin(p.angle-t.a),Math.cos(p.angle-t.a)))<.28;if(stage===3){if(near&&Math.abs(p.speed)<.05&&input.space){hold+=dt;if(hold>=3){rampArmed=true;say('Oprire stabilă. Pornește înainte pe rampă.');}}if(rampArmed&&p.z<29.5&&input.w){stage++;display();}}else if(near&&aligned&&Math.abs(p.speed)<.04&&(!(stage===1||stage===2)||reverse)){hold+=dt;if(hold>1){stage++;hold=0;if(stage===5){active=false;ui.hidden=true;s.message='Poligon terminat · '+mistakes+' atingeri de conuri. Repetă pentru un traseu fără greșeli.';s.messageUntil=s.time+10;p.speed=0;}else{display();say('Manevră încheiată. Următoarea zonă este marcată pe hartă.');}}}else hold=0;};
window.DriveTraining={start,clickControl,current:()=>stage<0?steps[step]?.[0]:null,gear:()=>gear,pedal:(id,down)=>{if(id in pedals)pedals[id]=!!down;},releasePedals,active:()=>active,cones,tasks,elevation:(x,z)=>x>17&&x<19&&z>29.5&&z<34.5?Math.min(.55,(z-29.5)*.275,(34.5-z)*.275):0};
})();
